class m_uvm_resource_default_converters;

   local static bit m_singleton = register();
   local function new();
   endfunction

   // Function- register
   // Explicitly initialize the singleton to eliminate race conditions
   //
   static function bit register();
      if (!m_singleton) begin

         `define __built_in(T) void'(m_uvm_resource_default_converter#(T)::register(`"T`"))

         `__built_in(shortint);
         `__built_in(int);
         `__built_in(longint);
         `__built_in(byte);
         `__built_in(bit);
         `__built_in(logic);
         `__built_in(reg);
         `__built_in(integer);
         `__built_in(time);
         `__built_in(real);
         `__built_in(realtime);
         `__built_in(string);
         `__built_in(uvm_bitstream_t);
         `__built_in(bit[7:0]);
         `__built_in(bit[15:0]);
         `__built_in(bit[31:0]);

         `undef __built_in

         m_singleton = 1;
      end
      return 1;
   endfunction
endclass

