virtual task wait_trigger_data (output T data);
	wait_trigger();
	data = get_trigger_data();
endtask

virtual task wait_ptrigger_data (output T data);
	wait_ptrigger();
	data = get_trigger_data();
endtask

virtual function void trigger (T data=null);
	int skip;
	skip=0;
	if (callbacks.size()) begin
		for (int i=0;i<callbacks.size();i++) begin
			uvm_event_callback#(T) tmp=callbacks[i];
			skip = skip + tmp.pre_trigger(this,data);
		end
	end
	if (skip==0) begin
		->m_event;
		if (callbacks.size()) begin
			for (int i=0;i<callbacks.size();i++) begin
				uvm_event_callback#(T) tmp=callbacks[i];
				tmp.post_trigger(this,data);
			end
		end
		num_waiters = 0;
		on = 1;
		trigger_time = $realtime;
		trigger_data = data;
	end
endfunction

virtual function T get_trigger_data ();
	return trigger_data;
endfunction

virtual function string get_type_name();
	return type_name;
endfunction

virtual function void do_print (uvm_printer printer);
	super.do_print(printer);
	printer.print_object("trigger_data", trigger_data);
endfunction

virtual function void do_copy (uvm_object rhs);
	uvm_event#(T) e;
	super.do_copy(rhs);
	if(!$cast(e, rhs) || (e==null)) return;
	trigger_data = e.trigger_data;
endfunction

