function int depth();
  return m_stack.size();
endfunction

function string get();
  string v;
  if(m_stack.size() == 0) return m_arg;
  get = m_stack[0];
  for(int i=1; i<m_stack.size(); ++i) begin
    v = m_stack[i];
    if(v != "" && (v[0] == "[" || v[0] == "(" || v[0] == "{"))
      get = {get,v};
    else
      get = {get,".",v};
  end
  if(m_arg != "") begin
    if(get != "")
      get = {get, ".", m_arg};
    else
      get = m_arg;
  end
endfunction

function string get_arg();
  return m_arg;
endfunction

function void set (string s);
  m_stack.delete();

  m_stack.push_back(s);
  m_arg = "";
endfunction

function void down (string s);
  m_stack.push_back(s);
  m_arg = "";
endfunction

function void down_element (int element);
  m_stack.push_back($sformatf("[%0d]",element));
  m_arg = "";
endfunction

function void up_element ();
  string s;
  if(!m_stack.size())
    return;
  s = m_stack.pop_back();
  if(s != "" && s[0] != "[")
    m_stack.push_back(s);
endfunction

function void up (byte separator =".");
  bit found;
  string s;
  while(m_stack.size() && !found ) begin
    s = m_stack.pop_back();
    if(separator == ".") begin
      if (s == "" || (s[0] != "[" && s[0] != "(" && s[0] != "{"))
        found = 1;
    end
    else begin
      if(s != "" && s[0] == separator)
        found = 1;
    end
  end
  m_arg = "";
endfunction

function void set_arg (string arg);
  if(arg=="") return;
  m_arg = arg;
endfunction

function void set_arg_element (string arg, int ele);
  string tmp_value_str;
  tmp_value_str.itoa(ele);
  m_arg = {arg, "[", tmp_value_str, "]"};
endfunction

function void unset_arg (string arg);
  if(arg == m_arg)
    m_arg = "";
endfunction

