    if (is_fatal)
      comp.uvm_report_fatal("NO_SET_CFG", {"no set_config to field '", FIELD,
                         "' for component '",comp.get_full_name(),"'"},
                         UVM_MEDIUM, `uvm_file , `uvm_line  );
