   else begin
      // Never set before
      m_cfg = new();
      m_cfg.db = db;
      m_cfg.scope = scope;
      m_cfg.stream_type_name = stream_type_name;
      m_cfg_dap.set(m_cfg);
      m_is_opened = 1;

